def roman_to_int(s):
    """Convert a standard Roman numeral string (with subtractive notation)
    to its integer value.

    I=1, V=5, X=10, L=50, C=100, D=500, M=1000
    """
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, ch in enumerate(s):
        v = values[ch]
        if i + 1 < len(s) and v < values[s[i + 1]]:
            total -= v  # subtractive notation, e.g. IV, IX, XL, XC, CD, CM
        else:
            total += v
    return total
```

