        while left >= 0 and right < n and s[left] == s[right]:
            left -= 1
            right += 1
        return right - left - 1

    for i in range(n):
        l = max(expand(i, i), expand(i, i + 1))
        if l > best_len:
            best_len = l
            best_start = i - (l - 1) // 2

    return s[best_start:best_start + best_len]
