        if not self._data:
            current_min = x
        else:
            current_min = x if x < self._data[-1][1] else self._data[-1][1]
        self._data.append((x, current_min))

    def pop(self):
        self._data.pop()

    def top(self):
        return self._data[-1][0]

    def get_min(self):
        return self._data[-1][1]
