def coin_change(coins, amount):
    """
    Return the fewest number of coins (unlimited supply) needed to make up
    `amount`, or -1 if it cannot be made.
    """
    if amount == 0:
        return 0

    coins = [c for c in coins if c > 0]
    if not coins:
        return -1

