def restore_ips(s):
    n = len(s)
    res = []
    if not 4 <= n <= 12:
        return []

    def backtrack(start, parts):
        if len(parts) == 4:
            if start == n:
                res.append('.'.join(parts))
            return
        left = 4 - len(parts) - 1  # parts still needed after this one
        for l in (1, 2, 3):
            end = start + l
            if end > n:
                break
            seg = s[start:end]
            # no leading zeros, value must be 0-255
            if (l > 1 and seg[0] == '0') or int(seg) > 255:
                break
            rem = n - end
            # remaining digits must fit exactly into the remaining parts
            if left <= rem <= left * 3:
                backtrack(end, parts + [seg])

    backtrack(0, [])
    return sorted(res)
