def spiral_order(m):
    """Return the elements of matrix m in clockwise spiral order."""
    result = []
    if not m or not m[0]:
        return result

    top, bottom = 0, len(m) - 1
    left, right = 0, len(m[0]) - 1

    while top <= bottom and left <= right:
        # Traverse top row left -> right
        for c in range(left, right + 1):
            result.append(m[top][c])
        top += 1

        # Traverse right column top -> bottom
        for r in range(top, bottom + 1):
            result.append(m[r][right])
        right -= 1

        # Traverse bottom row right -> left (if a row remains)
        if top <= bottom:
            for c in range(right, left - 1, -1):
                result.append(m[bottom][c])
            bottom -= 1

        # Traverse left column bottom -> top (if a column remains)
        if left <= right:
            for r in range(bottom, top - 1, -1):
                result.append(m[r][left])
            left += 1

    return result
